@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain
    securityFilterChain(
            HttpSecurity http
    ) throws Exception {

        return http
            .csrf(csrf -> csrf.disable())
            .authorizeHttpRequests(auth -> auth
                .requestMatchers(
                    "/auth/login"
                ).permitAll()
                .requestMatchers(
                    "/admin/**"
                ).hasRole("ADMIN")
                .anyRequest()
                .authenticated()
            )
            .build();
    }
}
